-- =============================================================================================
-- Hand-written below this line: text and location checks, numbering per property, SLA due
-- times, the allowed status transitions of requests and work orders (with the reasons they
-- need), a request resolved only when its work is done, derived timestamps owned by the
-- database, history written by the database for every status, assignee and priority change,
-- append-only history, costs corrected only by voiding, row-level security and grants. See
-- docs/architecture/DATA_MODEL.md section 7 (Maintenance).
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- Checks
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "maintenance_sla_targets" ADD CONSTRAINT "maintenance_sla_targets_minutes"
  CHECK ("response_minutes" > 0 AND "resolution_minutes" >= "response_minutes"
         AND "resolution_minutes" <= 525600);

ALTER TABLE "maintenance_requests" ADD CONSTRAINT "maintenance_requests_one_location"
  CHECK (num_nonnulls("unit_id", "common_area_id") = 1);
ALTER TABLE "maintenance_requests" ADD CONSTRAINT "maintenance_requests_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 120
         AND "description" = btrim("description") AND length("description") BETWEEN 1 AND 4000
         AND ("location_detail" IS NULL
              OR ("location_detail" = btrim("location_detail") AND length("location_detail") BETWEEN 1 AND 200))
         AND ("status_note" IS NULL
              OR ("status_note" = btrim("status_note") AND length("status_note") BETWEEN 1 AND 1000)));
-- Assigned by the insert trigger below.
ALTER TABLE "maintenance_requests" ADD CONSTRAINT "maintenance_requests_number_set"
  CHECK ("request_number" IS NOT NULL AND "request_number" >= 1);
ALTER TABLE "maintenance_requests" ADD CONSTRAINT "maintenance_requests_dates"
  CHECK ("reopen_count" >= 0
         AND ("status" <> 'RESOLVED' OR "resolved_at" IS NOT NULL)
         AND ("status" <> 'CLOSED' OR "closed_at" IS NOT NULL)
         AND ("status" = 'SUBMITTED' OR "status" IN ('REJECTED', 'CANCELLED') OR "accepted_at" IS NOT NULL));

ALTER TABLE "work_orders" ADD CONSTRAINT "work_orders_one_location"
  CHECK (num_nonnulls("unit_id", "common_area_id") = 1);
ALTER TABLE "work_orders" ADD CONSTRAINT "work_orders_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 120
         AND ("description" IS NULL
              OR ("description" = btrim("description") AND length("description") BETWEEN 1 AND 4000))
         AND ("status_note" IS NULL
              OR ("status_note" = btrim("status_note") AND length("status_note") BETWEEN 1 AND 1000)));
ALTER TABLE "work_orders" ADD CONSTRAINT "work_orders_number_set"
  CHECK ("work_order_number" IS NOT NULL AND "work_order_number" >= 1);
-- Open work has nobody on it; assigned, started, paused and completed work has someone.
ALTER TABLE "work_orders" ADD CONSTRAINT "work_orders_assignee"
  CHECK (CASE "status"
           WHEN 'OPEN' THEN "assigned_to_user_id" IS NULL
           WHEN 'CANCELLED' THEN true
           ELSE "assigned_to_user_id" IS NOT NULL
         END);
ALTER TABLE "work_orders" ADD CONSTRAINT "work_orders_dates"
  CHECK (("status" <> 'COMPLETED' OR ("completed_at" IS NOT NULL AND "started_at" IS NOT NULL))
         AND ("status" NOT IN ('IN_PROGRESS', 'ON_HOLD') OR "started_at" IS NOT NULL));

ALTER TABLE "work_order_costs" ADD CONSTRAINT "work_order_costs_amount_positive"
  CHECK ("amount_minor" > 0);
ALTER TABLE "work_order_costs" ADD CONSTRAINT "work_order_costs_currency_format"
  CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "work_order_costs" ADD CONSTRAINT "work_order_costs_text"
  CHECK ("description" = btrim("description") AND length("description") BETWEEN 1 AND 200
         AND ("void_reason" IS NULL
              OR ("void_reason" = btrim("void_reason") AND length("void_reason") BETWEEN 1 AND 500)));
ALTER TABLE "work_order_costs" ADD CONSTRAINT "work_order_costs_void"
  CHECK (("voided_at" IS NULL) = ("void_reason" IS NULL)
         AND ("voided_at" IS NULL) = ("voided_by_user_id" IS NULL));

ALTER TABLE "maintenance_events" ADD CONSTRAINT "maintenance_events_target"
  CHECK (num_nonnulls("request_id", "work_order_id") >= 1);
ALTER TABLE "maintenance_events" ADD CONSTRAINT "maintenance_events_note"
  CHECK ("body" IS NULL OR ("body" = btrim("body") AND length("body") BETWEEN 1 AND 2000));
-- A note has a text and an author.
ALTER TABLE "maintenance_events" ADD CONSTRAINT "maintenance_events_note_complete"
  CHECK ("type" <> 'NOTE' OR ("body" IS NOT NULL AND "actor_user_id" IS NOT NULL));

-- ---------------------------------------------------------------------------------------------
-- History: written by the triggers below for every status, assignee and priority change.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_maintenance_log(org uuid, prop uuid, request uuid, work_order uuid,
                                    kind "MaintenanceEventType", vis "MaintenanceEventVisibility",
                                    old_value text, new_value text, note text) RETURNS void
  LANGUAGE sql
  AS $$
    INSERT INTO "maintenance_events" ("id", "organisation_id", "property_id", "request_id", "work_order_id",
                                      "type", "visibility", "from_value", "to_value", "body", "actor_user_id")
    VALUES (gen_random_uuid(), org, prop, request, work_order, kind, vis, old_value, new_value, note,
            app_current_user_id())
  $$;

-- Location of new work: an ACTIVE unit or common area of a property that is not archived.
CREATE FUNCTION app_maintenance_location_active(prop uuid, unit uuid, area uuid) RETURNS void
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "properties" WHERE "id" = prop AND "status" = 'ARCHIVED') THEN
    RAISE EXCEPTION 'the property is archived' USING ERRCODE = 'check_violation';
  END IF;
  IF unit IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "units" WHERE "id" = unit AND "status" = 'ACTIVE') THEN
    RAISE EXCEPTION 'the unit is archived' USING ERRCODE = 'check_violation';
  END IF;
  IF area IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "common_areas" WHERE "id" = area AND "status" = 'ACTIVE') THEN
    RAISE EXCEPTION 'the common area is archived' USING ERRCODE = 'check_violation';
  END IF;
END
$$;

-- SLA due times of a request, from its creation and the property's target for the priority.
CREATE FUNCTION app_maintenance_set_due(r "maintenance_requests") RETURNS "maintenance_requests"
  LANGUAGE plpgsql
  AS $$
DECLARE
  target record;
BEGIN
  SELECT "response_minutes", "resolution_minutes" INTO target
    FROM "maintenance_sla_targets" WHERE "property_id" = r."property_id" AND "priority" = r."priority";
  IF FOUND THEN
    r."response_due_at" := r."created_at" + make_interval(mins => target."response_minutes");
    r."resolution_due_at" := r."created_at" + make_interval(mins => target."resolution_minutes");
  ELSE
    r."response_due_at" := NULL;
    r."resolution_due_at" := NULL;
  END IF;
  RETURN r;
END
$$;

-- ---------------------------------------------------------------------------------------------
-- Requests
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_maintenance_request_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."status" <> 'SUBMITTED' THEN
    RAISE EXCEPTION 'maintenance requests start submitted' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM app_maintenance_location_active(NEW."property_id", NEW."unit_id", NEW."common_area_id");
  -- Owned by the database: whatever the client sent is replaced.
  NEW."created_at" := now();
  NEW."status_note" := NULL;
  NEW."accepted_by_user_id" := NULL;
  NEW."accepted_at" := NULL;
  NEW."resolved_at" := NULL;
  NEW."closed_at" := NULL;
  NEW."reopen_count" := 0;
  NEW := app_maintenance_set_due(NEW);
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.maintenance_requests:' || NEW."property_id"::text, 0));
  SELECT coalesce(max("request_number"), 0) + 1 INTO NEW."request_number"
    FROM "maintenance_requests" WHERE "property_id" = NEW."property_id";
  RETURN NEW;
END
$$;

CREATE TRIGGER "maintenance_requests_insert"
  BEFORE INSERT ON "maintenance_requests"
  FOR EACH ROW EXECUTE FUNCTION app_maintenance_request_insert();

CREATE FUNCTION app_maintenance_request_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  transition text := OLD."status" || '>' || NEW."status";
  needs_note boolean;
BEGIN
  IF OLD."status" IN ('CLOSED', 'REJECTED', 'CANCELLED') THEN
    RAISE EXCEPTION 'maintenance request % is % and no longer changes', OLD."id", lower(OLD."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  -- The report itself never changes.
  IF (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."common_area_id", NEW."request_number",
      NEW."title", NEW."description", NEW."location_detail", NEW."submitted_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."common_area_id", OLD."request_number",
      OLD."title", OLD."description", OLD."location_detail", OLD."submitted_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'what was reported in maintenance request % never changes', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  -- Serialises with work orders of this request (see the work order triggers).
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.maintenance_request:' || OLD."id"::text, 0));

  -- Derived fields are owned by the database.
  NEW."accepted_by_user_id" := OLD."accepted_by_user_id";
  NEW."accepted_at" := OLD."accepted_at";
  NEW."resolved_at" := OLD."resolved_at";
  NEW."closed_at" := OLD."closed_at";
  NEW."reopen_count" := OLD."reopen_count";
  NEW."response_due_at" := OLD."response_due_at";
  NEW."resolution_due_at" := OLD."resolution_due_at";
  IF NEW."priority" IS DISTINCT FROM OLD."priority" THEN
    NEW := app_maintenance_set_due(NEW);
  END IF;

  IF NEW."status" = OLD."status" THEN
    NEW."status_note" := OLD."status_note";
    RETURN NEW;
  END IF;
  IF transition NOT IN ('SUBMITTED>ACCEPTED', 'SUBMITTED>REJECTED', 'SUBMITTED>CANCELLED',
                        'ACCEPTED>RESOLVED', 'ACCEPTED>CANCELLED',
                        'RESOLVED>CLOSED', 'RESOLVED>ACCEPTED') THEN
    RAISE EXCEPTION 'a maintenance request cannot go from % to %', lower(OLD."status"::text), lower(NEW."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  needs_note := transition IN ('SUBMITTED>REJECTED', 'SUBMITTED>CANCELLED', 'ACCEPTED>CANCELLED', 'RESOLVED>ACCEPTED');
  IF needs_note AND NEW."status_note" IS NULL THEN
    RAISE EXCEPTION 'give a reason to % this request',
      CASE transition WHEN 'SUBMITTED>REJECTED' THEN 'reject' WHEN 'RESOLVED>ACCEPTED' THEN 'reopen' ELSE 'cancel' END
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT needs_note THEN
    NEW."status_note" := NULL;
  END IF;

  IF transition = 'ACCEPTED>RESOLVED' AND NOT (
       EXISTS (SELECT 1 FROM "work_orders" WHERE "request_id" = OLD."id" AND "status" = 'COMPLETED')
       AND NOT EXISTS (SELECT 1 FROM "work_orders" WHERE "request_id" = OLD."id"
                                                 AND "status" NOT IN ('COMPLETED', 'CANCELLED'))) THEN
    RAISE EXCEPTION 'a request is resolved once its work is completed and no work is still open'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'CANCELLED' AND EXISTS (
       SELECT 1 FROM "work_orders" WHERE "request_id" = OLD."id" AND "status" NOT IN ('COMPLETED', 'CANCELLED')) THEN
    RAISE EXCEPTION 'cancel the open work orders of this request first' USING ERRCODE = 'check_violation';
  END IF;

  IF transition = 'SUBMITTED>ACCEPTED' THEN
    NEW."accepted_at" := now();
    NEW."accepted_by_user_id" := app_current_user_id();
  ELSIF NEW."status" = 'RESOLVED' THEN
    NEW."resolved_at" := now();
  ELSIF NEW."status" = 'CLOSED' THEN
    NEW."closed_at" := now();
  ELSIF transition = 'RESOLVED>ACCEPTED' THEN
    NEW."resolved_at" := NULL;
    NEW."reopen_count" := OLD."reopen_count" + 1;
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "maintenance_requests_guard"
  BEFORE UPDATE ON "maintenance_requests"
  FOR EACH ROW EXECUTE FUNCTION app_maintenance_request_guard();

CREATE FUNCTION app_maintenance_request_log() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."id", NULL, 'STATUS_CHANGED',
                                'RESIDENT', NULL, NEW."status"::text, NULL);
    RETURN NULL;
  END IF;
  IF NEW."status" IS DISTINCT FROM OLD."status" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."id", NULL, 'STATUS_CHANGED',
                                'RESIDENT', OLD."status"::text, NEW."status"::text, NEW."status_note");
  END IF;
  IF NEW."priority" IS DISTINCT FROM OLD."priority" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."id", NULL, 'PRIORITY_CHANGED',
                                'RESIDENT', OLD."priority"::text, NEW."priority"::text, NULL);
  END IF;
  RETURN NULL;
END
$$;

CREATE TRIGGER "maintenance_requests_log"
  AFTER INSERT OR UPDATE ON "maintenance_requests"
  FOR EACH ROW EXECUTE FUNCTION app_maintenance_request_log();

-- ---------------------------------------------------------------------------------------------
-- Work orders
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_work_order_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  req record;
BEGIN
  IF NEW."status" NOT IN ('OPEN', 'ASSIGNED') THEN
    RAISE EXCEPTION 'work orders start open or assigned' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."request_id" IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('veyra.maintenance_request:' || NEW."request_id"::text, 0));
    SELECT "status", "unit_id", "common_area_id" INTO req FROM "maintenance_requests" WHERE "id" = NEW."request_id";
    IF req."status" IS DISTINCT FROM 'ACCEPTED' THEN
      RAISE EXCEPTION 'work orders are raised for accepted requests only' USING ERRCODE = 'check_violation';
    END IF;
    IF (NEW."unit_id", NEW."common_area_id") IS DISTINCT FROM (req."unit_id", req."common_area_id") THEN
      RAISE EXCEPTION 'a work order is where its request is' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  PERFORM app_maintenance_location_active(NEW."property_id", NEW."unit_id", NEW."common_area_id");
  NEW."created_at" := now();
  NEW."status_note" := NULL;
  NEW."started_at" := NULL;
  NEW."completed_at" := NULL;
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.work_orders:' || NEW."property_id"::text, 0));
  SELECT coalesce(max("work_order_number"), 0) + 1 INTO NEW."work_order_number"
    FROM "work_orders" WHERE "property_id" = NEW."property_id";
  RETURN NEW;
END
$$;

CREATE TRIGGER "work_orders_insert"
  BEFORE INSERT ON "work_orders"
  FOR EACH ROW EXECUTE FUNCTION app_work_order_insert();

CREATE FUNCTION app_work_order_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  transition text := OLD."status" || '>' || NEW."status";
  needs_note boolean;
BEGIN
  IF OLD."status" IN ('COMPLETED', 'CANCELLED') THEN
    RAISE EXCEPTION 'work order % is % and no longer changes', OLD."id", lower(OLD."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."unit_id", NEW."common_area_id",
      NEW."work_order_number", NEW."created_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."request_id", OLD."unit_id", OLD."common_area_id",
      OLD."work_order_number", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'work order % cannot move to another request, place or number', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."request_id" IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('veyra.maintenance_request:' || OLD."request_id"::text, 0));
  END IF;
  NEW."started_at" := OLD."started_at";
  NEW."completed_at" := OLD."completed_at";

  IF NEW."status" = OLD."status" THEN
    NEW."status_note" := OLD."status_note";
    IF NEW."assigned_to_user_id" IS DISTINCT FROM OLD."assigned_to_user_id" AND NEW."status" = 'OPEN' THEN
      RAISE EXCEPTION 'assigning work moves it to assigned' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF transition NOT IN ('OPEN>ASSIGNED', 'OPEN>CANCELLED',
                        'ASSIGNED>OPEN', 'ASSIGNED>IN_PROGRESS', 'ASSIGNED>CANCELLED',
                        'IN_PROGRESS>ON_HOLD', 'IN_PROGRESS>COMPLETED', 'IN_PROGRESS>CANCELLED',
                        'ON_HOLD>IN_PROGRESS', 'ON_HOLD>CANCELLED') THEN
    RAISE EXCEPTION 'a work order cannot go from % to %', lower(OLD."status"::text), lower(NEW."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  needs_note := NEW."status" IN ('ON_HOLD', 'COMPLETED', 'CANCELLED');
  IF needs_note AND NEW."status_note" IS NULL THEN
    RAISE EXCEPTION 'say why the work is %',
      CASE NEW."status" WHEN 'ON_HOLD' THEN 'on hold' WHEN 'COMPLETED' THEN 'complete (what was done)' ELSE 'cancelled' END
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT needs_note THEN
    NEW."status_note" := NULL;
  END IF;
  IF NEW."status" = 'IN_PROGRESS' AND OLD."started_at" IS NULL THEN
    NEW."started_at" := now();
  ELSIF NEW."status" = 'COMPLETED' THEN
    NEW."completed_at" := now();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "work_orders_guard"
  BEFORE UPDATE ON "work_orders"
  FOR EACH ROW EXECUTE FUNCTION app_work_order_guard();

CREATE FUNCTION app_work_order_log() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'STATUS_CHANGED',
                                'INTERNAL', NULL, NEW."status"::text, NULL);
    IF NEW."assigned_to_user_id" IS NOT NULL THEN
      PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'ASSIGNEE_CHANGED',
                                  'INTERNAL', NULL, NEW."assigned_to_user_id"::text, NULL);
    END IF;
    RETURN NULL;
  END IF;
  IF NEW."status" IS DISTINCT FROM OLD."status" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'STATUS_CHANGED',
                                'INTERNAL', OLD."status"::text, NEW."status"::text, NEW."status_note");
  END IF;
  IF NEW."assigned_to_user_id" IS DISTINCT FROM OLD."assigned_to_user_id" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'ASSIGNEE_CHANGED',
                                'INTERNAL', OLD."assigned_to_user_id"::text, NEW."assigned_to_user_id"::text, NULL);
  END IF;
  IF NEW."priority" IS DISTINCT FROM OLD."priority" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'PRIORITY_CHANGED',
                                'INTERNAL', OLD."priority"::text, NEW."priority"::text, NULL);
  END IF;
  RETURN NULL;
END
$$;

CREATE TRIGGER "work_orders_log"
  AFTER INSERT OR UPDATE ON "work_orders"
  FOR EACH ROW EXECUTE FUNCTION app_work_order_log();

-- ---------------------------------------------------------------------------------------------
-- Costs: in the property's currency, not on cancelled work, corrected only by voiding once.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_work_order_cost_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."voided_at" IS NOT NULL THEN
    RAISE EXCEPTION 'a cost is recorded unvoided' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "properties" WHERE "id" = NEW."property_id" AND "currency" = NEW."currency") THEN
    RAISE EXCEPTION 'a cost is in the property''s currency' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM "work_orders" WHERE "id" = NEW."work_order_id" AND "status" = 'CANCELLED') THEN
    RAISE EXCEPTION 'cancelled work has no costs' USING ERRCODE = 'check_violation';
  END IF;
  NEW."created_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "work_order_costs_insert"
  BEFORE INSERT ON "work_order_costs"
  FOR EACH ROW EXECUTE FUNCTION app_work_order_cost_insert();

CREATE FUNCTION app_work_order_cost_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."voided_at" IS NOT NULL OR NEW."voided_at" IS NULL
     OR (NEW."organisation_id", NEW."property_id", NEW."work_order_id", NEW."kind", NEW."description",
         NEW."amount_minor", NEW."currency", NEW."recorded_by_user_id", NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."property_id", OLD."work_order_id", OLD."kind", OLD."description",
         OLD."amount_minor", OLD."currency", OLD."recorded_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'cost % is never edited; void it once and record it again', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  NEW."voided_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "work_order_costs_guard"
  BEFORE UPDATE ON "work_order_costs"
  FOR EACH ROW EXECUTE FUNCTION app_work_order_cost_guard();

-- ---------------------------------------------------------------------------------------------
-- Events: append-only. Only notes come from the application; everything else is written by the
-- triggers above (pg_trigger_depth() > 1 while they run).
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_maintenance_event_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  wo record;
BEGIN
  IF NEW."type" <> 'NOTE' AND pg_trigger_depth() < 2 THEN
    RAISE EXCEPTION 'maintenance history is written by the database; add a note instead'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW."work_order_id" IS NOT NULL THEN
    SELECT "request_id", "property_id" INTO wo FROM "work_orders" WHERE "id" = NEW."work_order_id";
    -- Notes on a work order also belong to its request, so the requester's timeline finds them.
    IF NEW."request_id" IS NULL THEN
      NEW."request_id" := wo."request_id";
    ELSIF NEW."request_id" IS DISTINCT FROM wo."request_id" THEN
      RAISE EXCEPTION 'a work order note belongs to that work order''s request' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  -- The wall-clock time of the event itself; "sequence" orders events written together.
  NEW."created_at" := clock_timestamp();
  RETURN NEW;
END
$$;

CREATE TRIGGER "maintenance_events_insert"
  BEFORE INSERT ON "maintenance_events"
  FOR EACH ROW EXECUTE FUNCTION app_maintenance_event_insert();

CREATE FUNCTION app_maintenance_event_append_only() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  RAISE EXCEPTION 'maintenance history is append-only' USING ERRCODE = 'insufficient_privilege';
END
$$;

CREATE TRIGGER "maintenance_events_append_only"
  BEFORE UPDATE OR DELETE ON "maintenance_events"
  FOR EACH ROW EXECUTE FUNCTION app_maintenance_event_append_only();
CREATE TRIGGER "maintenance_events_no_truncate"
  BEFORE TRUNCATE ON "maintenance_events"
  FOR EACH STATEMENT EXECUTE FUNCTION app_maintenance_event_append_only();

-- ---------------------------------------------------------------------------------------------
-- Row-level security and grants. Nothing is deleted; history is never updated.
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['maintenance_sla_targets', 'maintenance_requests', 'work_orders',
                           'work_order_costs', 'maintenance_events'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['maintenance_sla_targets', 'maintenance_requests', 'work_orders',
                           'work_order_costs'] LOOP
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "maintenance_sla_targets", "maintenance_requests", "work_orders", "work_order_costs",
              "maintenance_events" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "maintenance_requests", "work_orders", "work_order_costs" TO veyra_app;
-- SLA targets are configuration: replaced (deleted and added) when a property changes them.
GRANT SELECT, INSERT, UPDATE, DELETE ON "maintenance_sla_targets" TO veyra_app;
CREATE POLICY "maintenance_sla_targets_delete" ON "maintenance_sla_targets" FOR DELETE
  USING (organisation_id = app_current_organisation_id());
GRANT SELECT, INSERT ON "maintenance_events" TO veyra_app;
GRANT USAGE ON SEQUENCE "maintenance_events_sequence_seq" TO veyra_app;
